/**
 * Generates src/providers/index.ts from src/providers/providers.json.
 *
 * Each provider becomes a separate named export of a plain object literal,
 * so bundlers can drop the ones a consumer does not import.
 * With --check, exits 1 if the generated file is out of date instead of writing it.
 */
import fs from 'node:fs/promises';
import { cli } from 'cleye';
import type { Provider } from 'is-down/providers';

const sourcePath = new URL('../src/providers/providers.json', import.meta.url);
const outputPath = new URL('../src/providers/index.ts', import.meta.url);

const argv = cli({
	name: 'generate-providers',
	flags: {
		check: {
			type: Boolean,
			description: 'Exit 1 if src/providers/index.ts is out of date',
		},
	},
});

const source = JSON.parse(await fs.readFile(sourcePath, 'utf8')) as Record<string, Omit<Provider, 'id'>>;

// Formats values in the repository's lint style, so the generated file passes lint unchanged
const serialize = (value: unknown, indent: string): string => {
	if (typeof value === 'string') {
		return `'${value.replaceAll('\\', '\\\\').replaceAll('\'', String.raw`\'`)}'`;
	}

	const inner = `${indent}\t`;
	if (Array.isArray(value)) {
		if (value.length === 0) {
			return '[]';
		}
		const items = value.map(item => `${inner}${serialize(item, inner)},\n`);
		return `[\n${items.join('')}${indent}]`;
	}

	const properties = Object.entries(value as Record<string, unknown>).map(([key, item]) => {
		const name = /^[a-z_$][\w$]*$/i.test(key) ? key : serialize(key, inner);
		return `${inner}${name}: ${serialize(item, inner)},\n`;
	});
	return `{\n${properties.join('')}${indent}}`;
};

const providerExports = Object.entries(source).map(([id, data]) => {
	const provider: Provider = {
		id,
		...data,
	};
	return `export const ${id}: Provider = ${serialize(provider, '')};\n`;
});

const output = [
	'// Generated by scripts/generate-providers.ts from providers.json. Do not edit.',
	'import type { Provider } from \'./types.ts\';',
	'',
	'export type { Platform, Provider } from \'./types.ts\';',
	'',
	providerExports.join('\n'),
].join('\n');

if (argv.flags.check) {
	const current = await fs.readFile(outputPath, 'utf8').catch(() => '');
	if (current !== output) {
		process.stderr.write('src/providers/index.ts is out of date. Run `pnpm generate-providers`.\n');
		process.exitCode = 1;
	}
} else {
	await fs.writeFile(outputPath, output);
}
